func RenderBar(width int, percent float64, g GlyphSet) string {
	if width <= 0 {
		width = 18
	}
	percent = clamp01(percent)

	filled := int(percent * float64(width))
	remainder := percent*float64(width) - float64(filled)

	var sb strings.Builder
	sb.Grow(width * 3)
	for i := 0; i < width; i++ {
		if i < filled {
			sb.WriteString(g.Full)
			continue
		}
		if i == filled && len(g.Partial) > 0 && remainder > 0.0 {
			idx := int(remainder * float64(len(g.Partial)))
			if idx >= len(g.Partial) {
				idx = len(g.Partial) - 1
			}
			sb.WriteString(g.Partial[idx])
			continue
		}
		sb.WriteString(g.Empty)
	}
	return sb.String()
}

func RenderBarWithPercent(width int, percent float64, g GlyphSet) string {
	bar := RenderBar(width, percent, g)
	return bar + " **" + RenderPercent(percent) + "**"
}

func RenderBarWithLabel(width int, percent float64, label string, g GlyphSet) string {
	bar := RenderBar(width, percent, g)
	return fmt.Sprintf("`%s` %s  **%s**", bar, label, RenderPercent(percent))
}

func RenderPercent(p float64) string {
	return fmt.Sprintf("%d%%", int(math.Round(clamp01(p)*100)))
}

func RenderCounter(current, total int, g GlyphSet) string {
	if total <= 0 {
		total = 1
	}
	percent := float64(current) / float64(total)
	return RenderBarWithPercent(18, percent, g) + fmt.Sprintf("  (%d/%d)", current, total)
}

func RenderSteps(current, total int, g GlyphSet) string {
	if total <= 0 {
		return ""
	}
	var sb strings.Builder
	for i := 0; i < total; i++ {
		if i < current {
			sb.WriteString(g.Full)
		} else {
			sb.WriteString(g.Empty)
		}
	}
	return sb.String()
}

func RenderSpinnerFrame(frame int) string {
	frames := []string{"?", "?", "?", "?", "?", "?", "?", "?", "?", "?"}
	return frames[frame%len(frames)]
}

func RenderPulseFrame(frame int) string {
	frames := []string{"?", "?", "?", "?"}
	return frames[frame%len(frames)]
}

func RenderDotsFrame(frame int) string {
	frames := []string{".  ", ".. ", "...", " ..", "  .", "   "}
	return frames[frame%len(frames)]
}

func RenderLoadingBlock(frame int) string {
	spinner := RenderSpinnerFrame(frame)
	bar := RenderBar(12, float64(frame%12)/12.0, GlyphsBlock)
	return fmt.Sprintf("%s  `%s`", spinner, bar)
}

func RenderSegmented(width, filled int, full, empty string) string {
	if width <= 0 {
		return ""
	}
	if filled < 0 {
		filled = 0
	}
	if filled > width {
		filled = width
	}
	return strings.Repeat(full, filled) + strings.Repeat(empty, width-filled)
}

